import './app.css'; 

import InventoryDisplay from './inventory/getinventory';
import DisplayGrid from './gird/displaygrid';


function App() {
  return (
    <div>
      <h1 className="text-4xl font-bold text-center pt-8 pb-8">Welcome to FlaskCart 🍓</h1>

      
    <DisplayGrid />
    <InventoryDisplay />
    </div>
  );
}

export default App;
